PRAGMA foreign_keys = ON;
CREATE TABLE input_files(path TEXT PRIMARY KEY, bytes BLOB NOT NULL, sha256 TEXT NOT NULL, handling TEXT NOT NULL) STRICT;
CREATE TABLE instruments(id TEXT PRIMARY KEY, slug TEXT GENERATED ALWAYS AS (CASE WHEN input_path LIKE 'corpus/mx/%/instrument.json' THEN substr(input_path,11,instr(substr(input_path,11),'/')-1) ELSE id END) VIRTUAL UNIQUE, ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE provisions(row_id INTEGER PRIMARY KEY, id TEXT NOT NULL UNIQUE, instrument_id TEXT NOT NULL REFERENCES instruments(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), text TEXT NOT NULL, heading_title TEXT NOT NULL DEFAULT '', input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), label TEXT GENERATED ALWAYS AS(json_extract(extras,'$.label')) VIRTUAL, number TEXT GENERATED ALWAYS AS(json_extract(extras,'$.number')) VIRTUAL, provision_type TEXT GENERATED ALWAYS AS(json_extract(extras,'$.provision_type')) VIRTUAL, UNIQUE(input_path,ordinal), UNIQUE(input_path,source_pointer)) STRICT;
CREATE TABLE source_anchors(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('provision','instrument_title')), instrument_id TEXT NOT NULL REFERENCES instruments(id)) STRICT;
CREATE TABLE reference_edges(id TEXT PRIMARY KEY, source_provision_id TEXT NOT NULL REFERENCES source_anchors(id), target_instrument_id TEXT NOT NULL, target_provision_id TEXT NOT NULL, resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','historical_superseded_reference_outdated','historical_target_unavailable','unresolved')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), live_target TEXT GENERATED ALWAYS AS (CASE WHEN resolution_status='resolved' THEN target_provision_id END) VIRTUAL REFERENCES provisions(id), UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE reference_qualifiers(edge_id TEXT NOT NULL REFERENCES reference_edges(id) DEFERRABLE INITIALLY DEFERRED, ordinal INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(edge_id,ordinal)) STRICT;
CREATE TABLE outdated_reference_approvals(edge_id TEXT PRIMARY KEY REFERENCES reference_edges(id) DEFERRABLE INITIALLY DEFERRED, payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE legal_operator_reviews(edge_id TEXT PRIMARY KEY REFERENCES reference_edges(id) DEFERRABLE INITIALLY DEFERRED, payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE defined_terms(id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES instruments(id), defining_provision_id TEXT NOT NULL REFERENCES provisions(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), fraction TEXT GENERATED ALWAYS AS(json_extract(extras,'$.fraction')) VIRTUAL, inciso TEXT GENERATED ALWAYS AS(json_extract(extras,'$.inciso')) VIRTUAL, UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE term_usages(id TEXT PRIMARY KEY, provision_id TEXT NOT NULL REFERENCES provisions(id), term_id TEXT NOT NULL REFERENCES defined_terms(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE glossary_coverage(instrument_id TEXT PRIMARY KEY REFERENCES instruments(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), status TEXT GENERATED ALWAYS AS(json_extract(extras,'$.status')) VIRTUAL, UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE source_manifests(input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, instrument_id TEXT NOT NULL REFERENCES instruments(id), role TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), extras TEXT NOT NULL CHECK(json_valid(extras)), PRIMARY KEY(input_path,ordinal), UNIQUE(input_path,source_pointer)) STRICT;
CREATE TABLE enactment_evidence(id TEXT PRIMARY KEY, instrument_id TEXT NOT NULL REFERENCES instruments(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, extras TEXT NOT NULL CHECK(json_valid(extras)), UNIQUE(input_path,source_pointer), UNIQUE(input_path,ordinal)) STRICT;
CREATE TABLE evidence_artifacts(path TEXT PRIMARY KEY REFERENCES input_files(path), kind TEXT NOT NULL) STRICT;
CREATE TABLE corpus_release(id TEXT PRIMARY KEY, specification TEXT NOT NULL CHECK(json_valid(specification))) STRICT;
CREATE TABLE coverage(instrument_id TEXT NOT NULL, stage TEXT NOT NULL CHECK(stage IN ('acquired','structured','linked','analyzed')), state TEXT NOT NULL, source_path TEXT NOT NULL REFERENCES input_files(path), PRIMARY KEY(instrument_id,stage)) STRICT;
CREATE TABLE coverage_accepted_gaps(slug TEXT PRIMARY KEY, input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), extras TEXT NOT NULL CHECK(json_valid(extras)), UNIQUE(input_path,ordinal), UNIQUE(input_path,source_pointer)) STRICT;
CREATE TABLE standards_catalog(id TEXT PRIMARY KEY, metadata_path TEXT NOT NULL REFERENCES input_files(path), exclusion_reason TEXT NOT NULL) STRICT;
CREATE TABLE known_structural_debt(instrument_id TEXT NOT NULL, printed_label TEXT NOT NULL, input_path TEXT NOT NULL REFERENCES input_files(path), source_pointer TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), extras TEXT NOT NULL CHECK(json_valid(extras)), PRIMARY KEY(instrument_id,printed_label), UNIQUE(input_path,ordinal), UNIQUE(input_path,source_pointer)) STRICT;
CREATE TABLE instrument_reproducibility(instrument_id TEXT NOT NULL REFERENCES instruments(id), measuring_commit TEXT NOT NULL, status TEXT NOT NULL, evidence_path TEXT NOT NULL REFERENCES input_files(path), scope TEXT NOT NULL, PRIMARY KEY(instrument_id,measuring_commit,scope)) STRICT;
CREATE VIEW reproducibility_status AS SELECT i.id, coalesce(r.status,'not_assessed') AS status FROM instruments i LEFT JOIN instrument_reproducibility r ON r.instrument_id=i.id;
CREATE VIEW coverage_status_counts AS SELECT instrument_id,json_extract(extras,'$.temporal_status') AS temporal_status,json_extract(extras,'$.review_status') AS review_status,count(*) AS count FROM provisions GROUP BY instrument_id,temporal_status,review_status;
CREATE INDEX provisions_owner ON provisions(instrument_id,ordinal);
CREATE INDEX reference_targets ON reference_edges(target_provision_id);
CREATE INDEX term_occurrences ON term_usages(term_id);
CREATE VIRTUAL TABLE provisions_fts USING fts5(label,heading_title,text,content='provisions',content_rowid='row_id',tokenize='unicode61 remove_diacritics 2');
